INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128797, 'spa', 'Participio pasivo del Qal', 'Participio pasivo del Qal: el estado de estar extendido o desplegado, con función adjetival. En 1 R 8:54 Salomón se levanta de estar arrodillado con las manos ''extendidas'' hacia el cielo; en Os 5:1 una red está ''tendida'' sobre el Tabor; en Jl 2:2 la oscuridad está ''extendida'' sobre los montes como el alba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128810, 'spa', 'Una sola aparición en Ez 17', 'Una sola aparición en Ez 17:21 donde los fugitivos ''serán esparcidos'' a todo viento. La forma pasiva/Nifal y el contexto de dispersión lo vinculan naturalmente con el sentido de esparcimiento del sentido 4, y la evidencia multilingüe lo confirma. Probablemente representa una ocurrencia aislada que pertenece al sentido 4 más que un sentido independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128823, 'spa', 'Una sola aparición en Lm 4', 'Una sola aparición en Lm 4:4 que describe a un niño lactante cuya lengua se pega al paladar, con el participio פֹּרֵשׂ describiendo a ''quien parte'' el pan. La imagen es la de abrir el pan para repartirlo — una extensión concreta de ''separar'' que roza con ''dividir'' o ''distribuir.'' El español ''repartir'' capta bien este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128827, 'spa', 'Piel con significado de dispersión', 'Piel con significado de dispersión: esparcir o diseminar personas, extendiendo la metáfora física de ''desplegar'' a la dispersión de poblaciones. En Zac 2:6 Dios declara ''os esparcí como los cuatro vientos del cielo'' — una imagen impactante donde las personas son el objeto lanzado hacia afuera. Sal 68:14 usa de modo similar este sentido cuando los reyes son ''esparcidos.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128836, 'spa', 'Declarar con claridad', 'Levítico 24:12 y Números 15:34 describen la espera para ''declarar con precisión'' lo que debía hacerse en casos legales difíciles, subrayando la necesidad de instrucción divina clara. Nehemías 8:8 presenta a los levitas leyendo la Ley ''distintamente'' (מְפֹרָשׁ) para que el pueblo comprendiera. La noción central es claridad, precisión y hacer algo inequívocamente comprensible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128837, 'spa', 'Picadura venenosa metafórica', 'Proverbios 23:32 culmina una extensa advertencia contra el vino: «Al final muerde como serpiente y pica como víbora». La doble imagen de serpiente (serpiente/víbora, morder/picar) refuerza el peligro mediante paralelismo sinonímico. El pasaje más amplio (versículos 29-35) describe gráficamente los estragos del alcoholismo, y este verbo captura el dolor agudo e inesperado que sigue al placer inicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128838, 'spa', 'Lectura clara o traducida', 'Esdras 4:18 informa la respuesta del rey persa: «El documento que nos enviasteis ha sido leído claramente ante mí». Se debate si esto implica traducción del arameo al persa o simplemente una lectura oral cuidadosa. El contexto muestra que el contenido fue comprendido cabalmente, pues Artajerjes ordenó detener inmediatamente la reconstrucción de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128840, 'spa', 'Estiércol, excremento', 'Estiércol, contenido intestinal o despojos — el material de desecho extraído de un animal sacrificial durante su preparación. En la legislación sacerdotal, el פֶּרֶשׁ debe llevarse ''fuera del campamento'' y quemarse junto con la piel y la carne de las ofrendas por el pecado (Éx 29:14; Lv 4:11; 8:17; 16:27) y la vaca alazana (Nm 19:5). Su eliminación fuera del campamento subraya la impureza asociada a este material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128844, 'spa', 'Nombre propio manasita', 'En 1 Crónicas 7:16 se registra: «Maaca, esposa de Maquir, dio a luz un hijo y lo llamó פֶּרֶשׁ; su hermano se llamaba Seres.» Las glosas multilingües conservan el nombre propio mediante transliteración (Peres, Peresh). Esta nota genealógica sitúa a Peres dentro de la familia de Maquir, vinculándolo con el asentamiento de Galaad en el territorio oriental de Manasés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128845, 'spa', 'Caballo o corcel', 'Caballos o corceles, especialmente en contextos militares y comerciales. Sinónimo menos común de סוּס, con cognados en diversas lenguas semíticas (árabe faras, etiópico). Designa corceles importados de Togarmá (Ez 27:14), caballería real que un rey conscribirá (1 Sam 8:11), caballos veloces como langostas en la visión apocalíptica de Joel (Jl 2:4) y jinetes en batalla (Jer 46:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128846, 'spa', 'Guerrero montado o jinete, que aparece típicamente en plural junto a fuerzas de ', 'Guerrero montado o jinete, que aparece típicamente en plural junto a fuerzas de carros de guerra en narrativas militares. Los jinetes egipcios persiguen a Israel en el mar (Éx 14:9, 17-28), los parashim filisteos superan ampliamente en número a las fuerzas de Saúl (1 S 13:5), y Nahúm 3:3 describe la carga aterradora de la caballería ninivita. El cognado árabe fāris y el etiópico faras confirman la profunda asociación semítica de esta raíz con la monta a caballo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128865, 'spa', 'Copia documental', 'Esdras 7:11 introduce el decreto real: «Esta es la copia del documento que el rey Artajerjes entregó a Esdras.» Los versículos siguientes (7:12-26) contienen el texto del decreto que autoriza el regreso de Esdras a Jerusalén, el financiamiento del templo y la autoridad legal para aplicar la Torá. La fórmula «esta es la copia» señala que estamos ante una transcripción oficial del original persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128866, 'spa', 'copia de documento', 'Una copia o duplicado de documento oficial escrito, específicamente decretos reales. Ester 3:14 ordena: ''Una copia del edicto (פַּתְשֶׁ֫גֶן הַכְּתָב) debía ser promulgada como ley en cada provincia.'' Ester 4:8: Mardoqueo dio a Hatac ''una copia del decreto escrito (פַּתְשֶׁ֫גֶן כְּתָב־הַדָּת)'' ordenando aniquilación judía, para que Ester pudiera leerlo. Ester 8:13: ''Una copia del edicto (פַּתְשֶׁ֫גֶן הַכְּתָב)'' permitiendo defensa judía debía distribuirse por todas las provincias. Refleja prácticas administrativas persas de duplicación oficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128867, 'spa', 'copia de carta', 'Una copia o duplicado de documento o carta oficial, específicamente en correspondencia imperial persa. Esdras 4:11 introduce: ''Esta es una copia de la carta (פַּרְשֶׁ֫גֶן אִגַּרְתָּא) que le enviaron [a Artajerjes]''—enemigos acusando a los constructores de Jerusalén. Versículo 23: ''cuando la copia de la carta del rey Artajerjes (פַּרְשֶׁ֫גֶן נִשְׁתְּוָנָא דִּי אַרְתַּחְשַׁשְׂתְּא מַלְכָּא) fue leída ante Rehum,'' detuvieron la construcción. Esdras 5:6: Tatnai envió ''copia de la carta'' consultando sobre autorización de reconstrucción. Refleja duplicación oficial de correspondencia administrativa persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128868, 'spa', 'Excremento o inmundicia', 'Jueces 3:22 describe el asesinato de Eglón por Ehúd: «También la empuñadura entró tras la hoja, y la grasa se cerró sobre la hoja... y salió el excremento.» Las glosas multilingües reflejan incertidumbre sobre si se trata de heces u otra materia anatómica. Sea cual sea la lectura precisa, el relato enfatiza la brutalidad física del acto, empleando un detalle visceral que resalta la victoria de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128870, 'spa', 'Extender o desplegar', 'Job 26:9 describe las acciones de Dios: «Cubre la faz de la luna llena, extendiendo su nube sobre ella.» Las glosas multilingües apoyan la imagen de extensión o despliegue. Ya se conserve el infinitivo o se enmiende a participio, el cuadro permanece: Dios despliega activamente las nubes como un velo sobre la luna, dentro del catálogo de su poder soberano sobre la creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128871, 'spa', 'Hijo de Amán', 'Ester 9:7 inicia la lista de los hijos de Amán: «Mataron también a Parsandata, Dalfón, Aspata...» y así los diez nombres. La enumeración individual de cada uno subraya la totalidad de la acción: toda la casa de Amán fue eliminada, suprimiendo la amenaza de forma definitiva. Esta justicia completa se convirtió en parte integral de la celebración de Purim.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128872, 'spa', 'Éufrates (río, nombre propio) — El sustantivo propio Perat (Éufrates), que desig', 'Éufrates (río, nombre propio) — El sustantivo propio Perat (Éufrates), que designa el mayor río de Asia occidental. Identificado como uno de los cuatro ríos del Edén (Gn 2:14), sirve como la frontera norte ideal de la tierra prometida (Gn 15:18; Dt 1:7; 11:24; Jos 1:4). Usado en narrativas históricas referentes a campañas cerca del Éufrates (2 S 8:3; 2 Re 23:29; 24:7; Jer 46:2) y en los actos simbólicos de Jeremías (Jer 13:4-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128877, 'spa', 'Nobles de la corte', 'Nobles, altos funcionarios o aristócratas—la clase de élite en las cortes persas y babilónicas. Ester 1:3: Asuero hizo un banquete ''para todos sus funcionarios y siervos, el ejército de Persia y de Media, los nobles (הַפַּרְתְּמִים) y los gobernadores de las provincias.'' Ester 6:9: Amán debe hacer que ''uno de los funcionarios más nobles del rey (מִשָּׂרֵי הַמֶּלֶךְ הַפַּרְתְּמִים)'' conduzca a Mardoqueo en el caballo del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128878, 'spa', 'Transgresión incierta', 'Job 35:15 en el Texto Masorético contiene este término incierto dentro del discurso de Elihú sobre la justicia divina y la responsabilidad humana. Las glosas multilingües reflejan división: algunas siguen la enmienda hacia ''transgresión''. El argumento de Elihú es que el silencio de Dios no debe confundirse con indiferencia ante el mal, pues Él ve la transgresión aun cuando no actúa de inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128879, 'spa', 'Extenderse o avanzar, usado intransitivamente de una erupción cutánea (tsara''at)', 'Extenderse o avanzar, usado intransitivamente de una erupción cutánea (tsara''at) que progresa por la piel o la tela durante el proceso de inspección sacerdotal. Cada una de sus veintidós apariciones cae dentro de Levítico 13-14, lo que lo convierte en un término puramente cúltico-médico. La construcción se empareja frecuentemente con ''en la piel'' (ba''or) o ''en la vestidura'' (babbeged), y el infinitivo absoluto (pasoh yifseh) intensifica la certeza del diagnóstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128882, 'spa', 'Desgarrar como presa', 'Lamentaciones 3:11 emplea una imagen gráfica de depredador: ''Me desvió del camino y me despedazó; me dejó devastado''. Este versículo sigue las metáforas del león y el oso (versículo 10), con Dios representado como fiera que ataca a su presa. El lenguaje impactante cumple el propósito del lamento: articular con honestidad el sufrimiento, sin disimular la acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128883, 'spa', 'Pasjur (nombre propio)', 'Pasjur (nombre propio). El nombre propio Pasjur (פַּשְׁחוּר), que designa a múltiples individuos en la literatura profética y posexílica. Las transliteraciones en distintas lenguas — inglés ''Pashhur'', español ''Pasjur'', francés/alemán ''Paschur'', griego Πασχωρ — muestran una adaptación fonética consistente. El peso narrativo principal del nombre recae sobre el antagonista de Jeremías (Jer 20:1–6), pero también encabeza un importante clan sacerdotal que retornó del exilio (Esd 2:38).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128887, 'spa', 'Despojar a los caídos en el campo de batalla — 3 ocurrencias (1 S 31', 'Despojar a los caídos en el campo de batalla — 3 ocurrencias (1 S 31:8; 2 S 23:10; 1 Cr 10:8) que describen el acto de saquear los cadáveres después de la batalla. Tras la batalla de Gilboa, los filisteos vienen «a despojar a los muertos». Constituye un puente entre el sentido 1 (asalto) y el sentido 2 (despojo de vestiduras).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128888, 'spa', 'Qal', 'Qal: hacer una incursión militar repentina o lanzarse al ataque — 14 ocurrencias concentradas en las narrativas de Jueces y Samuel. Los hombres de Abimelec «se lanzan» sobre Siquem (Jue 9:33, 44); los filisteos «asaltan» el territorio israelita (1 S 27:8, 10; 30:1). El enmarcado narrativo con verbos de movimiento direccional subraya la rapidez y sorpresa del ataque.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128889, 'spa', 'Hifil causativo', 'Hifil causativo: despojar de ropa o armadura a otra persona por la fuerza — 11 ocurrencias, siempre con objeto directo que especifica a la víctima. Los hermanos de José le quitan su túnica (Gn 37:23); Aarón es despojado de sus vestiduras sacerdotales en el monte Hor (Nm 20:26, 28); los filisteos despojan el cadáver de Saúl (1 S 31:9; 1 Cr 10:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128891, 'spa', 'Qal reflexivo o intransitivo', 'Qal reflexivo o intransitivo: quitarse las propias vestiduras — 9 ocurrencias incluida la forma Hitpael reflexiva. El sacerdote se quita sus vestiduras de lino tras la ofrenda por el pecado (Lv 6:11; 16:23); Jonatán se quita su manto y se lo da a David (1 S 18:4); Saúl se despoja de su ropa y profetiza desnudo (1 S 19:24); la amada del Cantar dice «Me he quitado mi túnica» (Cnt 5:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128892, 'spa', 'Uso extendido o metafórico de despojar o desprenderse — 2 ocurrencias', 'Uso extendido o metafórico de despojar o desprenderse — 2 ocurrencias. En Oseas 7:1 el contexto habla de un ladrón que «despoja»; Nahúm 3:16 emplea la imagen de la langosta que «se despoja» de sus alas membranosas, metáfora vívida de los mercaderes de Nínive que se dispersan tras saquear la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128904, 'spa', 'Hifil especializado', 'Hifil especializado: desollar o despellejar un animal sacrificial — 4 ocurrencias en contextos cultuales. En Levítico 1:6 el oferente «desuella» el holocausto; en 2 Crónicas 29:34 y 35:11 los levitas ayudan con el desuello durante las reformas de Ezequías y Josías. Miqueas 3:3 extiende la imagen metafóricamente a los gobernantes opresores que «desuellan» la piel del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128921, 'spa', 'Avance militar', 'Isaías 27:4 presenta la pregunta retórica de Dios en el cántico de la viña: ''¿Quién me diera zarzas y espinos en batalla? Yo marcharía contra ellos y los quemaría juntos''. El contexto muestra un cambio en la relación de Dios con su viña: ya no airado y destructivo (como en Isaías 5), sino protector y dispuesto a combatir contra cualquier amenaza externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128922, 'spa', 'Alzarse en rebelión contra un soberano o autoridad política, rechazando la lealt', 'Alzarse en rebelión contra un soberano o autoridad política, rechazando la lealtad y rompiendo un tratado de vasallaje. Es el sentido concreto e histórico: Moab «se rebeló» contra Israel tras la muerte de Acab (2 R 1:1; 3:5, 7), y Edom «se sublevó» de bajo la mano de Judá (2 R 8:20, 22). Isaías 1:2 tiende un puente hacia la esfera teológica: «Crié hijos y los engrandecí, pero se rebelaron contra mí.»');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128925, 'spa', 'Quien habitual o característicamente se rebela o transgrede, usado como sustanti', 'Quien habitual o característicamente se rebela o transgrede, usado como sustantivo a partir del participio Qal para designar una clase de personas definidas por su rebeldía. Isaías 1:28 advierte que «los transgresores y pecadores serán quebrantados juntamente», e Isaías 53:12 declara que el Siervo «fue contado con los transgresores». La forma sustantivada cristaliza la rebelión como rasgo identitario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128926, 'spa', 'Violar, traspasar o quebrantar una ley divina, una estipulación del pacto o un l', 'Violar, traspasar o quebrantar una ley divina, una estipulación del pacto o un límite moral, enfatizando la ofensa en sí más que la rebeldía política. Jeremías 2:29 pregunta: «¿Por qué contendéis conmigo? Todos habéis transgredido contra mí»; Isaías 59:13 lo empareja con «hablar opresión y rebelión». Se distingue del sentido 1 por su foco en la violación normativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128942, 'spa', 'Ser objeto de transgresión, ser ofendido o agraviado — el Nifal pasivo, que indi', 'Ser objeto de transgresión, ser ofendido o agraviado — el Nifal pasivo, que indica al que sufre la ofensa y no al que la comete. Aparece solamente en Proverbios 18:19: «El hermano ofendido (נִפְשָׁע) es más difícil de ganar que una ciudad fortificada.» Esta rara forma pasiva transforma la perspectiva del verbo, desplazando el foco del rebelde a la parte herida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128947, 'spa', 'Paso de distancia', '1 Samuel 20:3 recoge la súplica urgente de David: ''Apenas hay un paso entre mí y la muerte''. Jonatán se ha mostrado escéptico sobre los planes de su padre para matar a David, pero David insiste en que Saúl oculta su intención. La imagen del ''paso'' hace tangible el peligro: la muerte no es solo posible, sino inminente, y exige acción inmediata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128948, 'spa', 'Transgresión u ofensa deliberada contra Dios — una violación voluntaria de la le', 'Transgresión u ofensa deliberada contra Dios — una violación voluntaria de la ley divina, las estipulaciones del pacto o los estándares morales. Este sentido dominante cubre formas singulares y plurales en todos los contextos gramaticales. Es central en textos confesionales y proféticos: Éx 34:7 (''que perdona la iniquidad y la transgresión''), Is 53:5 (''fue herido por nuestras transgresiones''), y la fórmula de Amós ''por tres transgresiones y por cuatro.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128965, 'spa', 'Rebelión o revuelta contra la autoridad soberana — ya sea la soberanía divina o ', 'Rebelión o revuelta contra la autoridad soberana — ya sea la soberanía divina o el señorío político — con énfasis en la ruptura relacional de quebrantar la lealtad. Éx 23:21 advierte a Israel que no se rebele contra el ángel de Dios; Lv 16:21 incluye פְּשָׁעִים en la confesión del Día de la Expiación que abarca toda clase de transgresión. Este sentido destaca la dimensión de insurrección y deslealtad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128995, 'spa', 'Sustantivo arameo que designa la interpretación, específicamente de sueños y vis', 'Sustantivo arameo que designa la interpretación, específicamente de sueños y visiones en las narrativas cortesanas y las visiones apocalípticas de Daniel. Nombra lo que los sabios babilónicos no pueden proporcionar (Dn 2:4-11; 4:3-4; 5:7-8) y lo que Dios revela exclusivamente a través de Daniel (Dn 2:27-45; 4:15-16; 5:12-26). Las formas enfática פִּשְׁרָא y constructa פְּשַׁר alternan a lo largo del libro. Este término influyó posteriormente en el método de interpretación pesher de Qumrán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129003, 'spa', 'Interpretación sapiencial', 'El término aparece en el contexto de la sabiduría y el entendimiento, preguntando retóricamente quién posee la capacidad de interpretar un asunto difícil. La evidencia multilingüe (español ''interpretación'', francés conservando la forma hebrea) sugiere un término técnico para la perspicacia hermenéutica, el desentrañar enigmas que requieren una lectura más profunda que la superficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129004, 'spa', 'Lino (material) — Lino como planta cruda y como producto textil acabado — dos et', 'Lino (material) — Lino como planta cruda y como producto textil acabado — dos etapas del mismo material que el hebreo no separa léxicamente. Como planta, aparece secándose en el techo de Rahab (Jos 2:6) y prendiéndose fuego en las ataduras de Sansón (Jue 15:14). Como tela acabada, aparece en la legislación sacerdotal sobre contaminación de vestiduras junto a la lana (Lv 13:47-59), en la prohibición de telas mixtas (Dt 22:11), y en la vestimenta sacerdotal de Ezequiel (Ez 44:17-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129013, 'spa', 'Lino y mecha', 'Éxodo 9:31 describe el cultivo literal de lino destruido durante las plagas de Egipto. Isaías 42:3 usa la imagen de una mecha humeante (''no apagará la mecha que apenas arde'') para mostrar el trato gentil del Siervo hacia los débiles. Isaías 43:17 emplea la misma imagen de mecha (''se apagan, se extinguen como mecha'') para representar la derrota militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129014, 'spa', 'Bocado, pedazo de pan', 'Bocado, pedazo de pan. Un bocado o fragmento de alimento, especialmente pan (פַּת). El término funciona en fórmulas de hospitalidad (Gn 18:5; Jue 19:5; 1 S 28:22), sabiduría proverbial sobre la satisfacción (Pr 17:1; 23:8), juramentos de integridad personal (Job 31:17) e instrucciones rituales para la ofrenda de cereal donde la ofrenda se parte en pedazos (Lv 2:6; 6:21). Evoca la porción más simple y básica del sustento humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129025, 'spa', 'Pedazos de pan', 'Usado en Ezequiel 13:19 dentro de una severa crítica a los falsos profetas que profanan a Dios por puñados de cebada y pedazos de pan. La palabra subraya la pequeñez e insignificancia de lo que estos charlatanes aceptan como pago por corromper la verdad, revelando la vileza de su traición espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129027, 'spa', 'Adverbio que expresa una ocurrencia abrupta e imprevisible, a menudo con matices', 'Adverbio que expresa una ocurrencia abrupta e imprevisible, a menudo con matices de alarma o catástrofe. Modifica con mayor frecuencia la llegada de calamidades: la destrucción cae פִּתְאֹם sobre Babilonia (Isa 47:11; 48:3), las tiendas de Jeremías son ''repentinamente devastadas'' (Jer 4:20; 6:26; 15:8; 51:8), y la ruina del insensato llega sin remedio (Prov 6:15; 24:22). También describe el habla o la acción divina que irrumpe sin anticipación humana: YHWH ''dijo de repente a Moisés, Aarón y Miriam'' (Núm 12:4). La frase aliterativa triple פֶּתַע פִּתְאֹם (''en un instante, de repente,'' Isa 29:5; Núm 6:9; 35:22) intensifica el elemento de conmoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129032, 'spa', 'Manjar real', 'Manjar real o alimento selecto porcionado de la propia mesa del rey. Usado exclusivamente en el libro de Daniel (1:5, 8, 13, 15, 16; 11:26) para las provisiones ofrecidas a los jóvenes judíos cautivos y luego para la comida de quienes comen en la mesa de un gobernante. El origen persa subraya el contexto de la corte babilónica. Las traducciones multilingües convergen estrechamente en el sentido de alimento distinguido de origen regio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129039, 'spa', 'Palabra, mensaje o decreto', 'Una palabra, mensaje, decreto o comunicación oficial, préstamo arameo del persa patigama. Se emplea para edictos reales (Esd 6:11), cartas oficiales (Esd 4:17; 5:7), respuestas formales (Esd 5:11) y de manera más amplia para un asunto o cuestión (Dan 3:16; 4:17). En español, ''mensaje'' y ''asunto'' capturan bien el doble registro de este término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129043, 'spa', 'Ensanchar, expandir', 'Las tres ocurrencias abarcan desde la bendición territorial de Dios para Jafet (Génesis 9:27) hasta advertencias proverbiales sobre el habla (Proverbios). El alemán ''weit-mache'' (hacer amplio) y el francés ''que-enlarge'' preservan el sentido espacial, mientras que las traducciones españolas se conectan con actos de habla (''engañarás''—engañar). El tema Piel sugiere acción intensiva o causativa: hacer que algo se vuelva espacioso o hacer que la boca se abra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129044, 'spa', 'El Piel activo de seducción y persuasión, cuya valencia moral oscila entre el en', 'El Piel activo de seducción y persuasión, cuya valencia moral oscila entre el engaño y la influencia legítima. Éxodo 22:16 lo usa para seducir a una virgen no desposada; Jueces 14:15 y 16:5 para la insistente persuasión de Dalila sobre Sansón. En la escena del consejo celestial (1 Re 22:20-22), un espíritu se ofrece a ''seducir'' a Acab — la persuasión como estrategia sancionada por Dios. El español ''seducir'' y ''persuadir'' reflejan bien esta ambigüedad moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129047, 'spa', 'El Piel con una fuerza explícitamente negativa y engañosa', 'El Piel con una fuerza explícitamente negativa y engañosa: engañar, inducir a error, deludir. Jeremías 20:7 es el texto decisivo — ''Me sedujiste (פִּתִּיתָנִי), oh SEÑOR'' — donde el profeta acusa a Dios de haberlo atrapado. El Salmo 78:36 describe a Israel adulando a Dios ''con su boca'' mientras su corazón era falso. Ezequiel 14:9 advierte que si un profeta es engañado, ''yo, YHWH, engañé a ese profeta.'' El español ''engañar'' y ''seducir'' captan la duplicidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129048, 'spa', 'El Pual pasivo', 'El Pual pasivo: ser persuadido o engañado por la acción de otro. Proverbios 25:15 dice ''con paciencia se persuade al gobernante'' — aquí la persuasión es constructiva. Pero Jeremías 20:10 y Ezequiel 14:9 usan el Pual para ser fatalmente engañado. El Pual destaca el estado consumado de haber sido persuadido, más que el proceso (Nifal). Tres atestiguaciones abarcan el espectro moral, desde la diplomacia sabia hasta el engaño fatal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129052, 'spa', 'El Nifal y el Qal pasivo', 'El Nifal y el Qal pasivo: ser seducido, dejarse engañar. Jeremías 20:7b completa el versículo — ''y fui seducido (וָאֶפָּת)'' — la contraparte pasiva del engaño activo de Dios. Deuteronomio 11:16 advierte ''guardaos que vuestro corazón no sea seducido,'' y Job 31:9, 27 confiesan el peligro de un corazón ''secretamente seducido.'' El matiz reflexivo sugiere una credulidad culpable — estar abierto a la seducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129056, 'spa', 'El participio Qal como adjetivo sustantivado', 'El participio Qal como adjetivo sustantivado: simple, ingenuo, crédulo. Oseas 7:11 llama a Efraín ''paloma incauta, sin entendimiento'' (יוֹנָה פוֹתָה) — fácilmente atraída por cualquier potencia pasajera. Job 5:2 advierte que ''la irritación mata al simple.'' Este sentido revela el núcleo psicológico de la raíz: la persona פָּתָה es ''abierta'' — quizás de mente abierta, pero peligrosamente abierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129066, 'spa', 'Nombre propio', 'Nombre propio del padre de Joel (Joel 1:1). Aunque aparece solo una vez, establece la identidad y el linaje del profeta. Las traducciones multilingües conservan la transliteración «Petuel», como es habitual con los nombres personales que anclan a figuras históricas en el registro bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129067, 'spa', 'Grabado, obra tallada', 'El acto o producto de tallar letras o diseños en piedra, metal o gemas. Se concentra en las instrucciones para las vestiduras sacerdotales (Éx 28:11, 21, 36; 39:6, 14), donde los nombres tribales se graban en piedras de ónice y gemas del pectoral «como grabados de sello». El término «grabado» capta la idea de artesanía incisa y permanente, distinguiéndola de otros tipos de trabajo ornamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129073, 'spa', 'Abrir (Qal transitivo)', 'Sentido básico en Qal transitivo ''abrir'' (67 veces): abrir un objeto físico —puerta, portón, ventana, saco, recipiente, libro, boca—. Noé ''abrió la ventana'' (Gn 8:6), Jehová ''abrió su vientre'' (Gn 29:31, 30:22), José ''abrió todos los graneros'' (Gn 41:56), los hermanos ''abrieron sus sacos'' (Gn 42:27). También ojos (2 R 6:17) y puertas de prisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129074, 'spa', 'Abierto (participio estativo)', 'Participio pasivo de Qal ''abierto, que permanece abierto'' (13 veces): describe un estado de apertura con fuerza adjetival. Nm 19:15 ''toda vasija abierta'', Jos 8:17 ''dejaron la ciudad abierta'', 1 R 8:29, 52 ''que tus ojos estén abiertos''. Se distingue del verbo activo por su carácter estativo y adjetival.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129075, 'spa', 'Ser abierto (Nifal pasivo)', 'Nifal pasivo ''ser abierto'' (14 veces): la forma pasiva directa referida a puertas, cielos, ojos u oídos que se abren. Gn 7:11 ''las ventanas de los cielos fueron abiertas'', Neh 7:3 ''que no se abran las puertas'', Is 24:18 ''las ventanas de lo alto se abrirán'', Job 12:14 ''al que él encierra, no se le puede abrir''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129079, 'spa', 'Abrir (boca/ojos/mano)', 'Qal ''abrir boca/labios/ojos/mano'' (13 veces): el sentido básico aplicado a partes del cuerpo, a menudo metafórico para el habla o la percepción. Dt 15:8, 11 ''abrirás tu mano generosamente'', Job 31:32 ''abrí mis puertas al caminante'', Sal 38:13 ''no abro mi boca''. Semánticamente muy cercano al sentido 1, pero orientado a lo corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129091, 'spa', 'Soltar, desatar (Piel)', 'Piel ''soltar, desatar'' (14 veces): forma intensiva/factitiva para aflojar ligaduras, grillos, cilicio o cinturón, distinta del simple ''abrir''. Gn 24:32: Labán ''desató los camellos''; Job 12:18 ''él suelta las ataduras de los reyes''; Job 38:31 ''¿podrás soltar las cuerdas del Orión?''; Sal 116:16 ''tú desataste mis prisiones''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129093, 'spa', 'Liberar, poner en libertad (Piel)', 'Piel ''poner en libertad, liberar'' (6 veces): extensión del sentido ''soltar'' aplicada a personas —liberación de cautivos o prisioneros—. Sal 102:20 ''para soltar a los sentenciados a muerte'', Sal 105:20 ''el rey envió y lo liberó'', Is 51:14 ''el cautivo pronto será suelto''. El contexto de cautiverio o esclavitud lo distingue del simple ''desatar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129094, 'spa', 'Abrirse, irrumpir (intransitivo)', 'Qal/Nifal intransitivo ''abrirse, irrumpir'' (4 veces): algo que se abre o revienta sin agente externo. Sal 106:17 ''se abrió la tierra y tragó'', Is 35:5 ''los oídos de los sordos se destaparán'', Is 45:8 ''ábrase la tierra'', Jer 1:14 ''del norte se desatará el mal''. La fuerza intransitiva se distingue claramente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129107, 'spa', 'Soltarse a sí mismo (Hitpael)', 'Hitpael reflexivo ''soltarse, liberarse'' (2 veces): contrapartida reflexiva del Piel, liberarse uno mismo de las ataduras. Is 52:2 ''suéltate de las cadenas de tu cuello, cautiva hija de Sion'' (tanto Ketiv como Qere). Forma muy rara que confirma el sentido reflexivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129128, 'spa', 'Desenvainar (espada)', 'Qal ''desenvainar (una espada)'' (2 veces): sentido especializado de sacar la espada de su vaina. Sal 37:14 ''los impíos desenvainaron la espada'', Ez 21:28 ''espada, espada desenvainada''. Las traducciones multilingües distinguen claramente este uso del ''abrir'' genérico mediante vocabulario específico de ''desenvainar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129144, 'spa', 'Aflojarse (incierto)', 'Una ocurrencia incierta en Is 5:27, traducida como ''aflojado'' o ''desatado'', posiblemente Nifal referido a un cinturón o atadura: ''ni el cinturón de sus lomos se desatará''. Podría pertenecer al sentido 3 (Piel soltar) o al sentido 2 (Nifal ser abierto), pero la incertidumbre textual o contextual justifica un registro aparte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129157, 'spa', 'Grabar (Piel/Pual)', 'Grabar o cincelar diseños decorativos o inscripciones sobre piedra, metal o madera, usado exclusivamente en las formas Piel y Pual para indicar artesanía especializada. El acusativo cognado פִּתּוּחֵי חוֹתָם (''grabados de sello'') en Éxodo 28:11, 36 y 39:6 destaca la precisión requerida. Las traducciones en diversos idiomas apuntan uniformemente al trabajo artesanal de incisión sobre materiales duros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129166, 'spa', 'Entrada o abertura', 'La abertura, entrada o vano de una tienda, tabernáculo, templo, casa, cueva o ciudad —el espacio o umbral que se atraviesa para ingresar—. Es el uso dominante en 148 ocurrencias, típicamente en estado constructo (''entrada de la tienda'', ''entrada de la puerta''). Gn 18:1 sitúa a Abraham ''a la entrada de la tienda''; la legislación de Levítico y Números emplea la fórmula ''entrada del Tabernáculo de Reunión'' con gran frecuencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129174, 'spa', 'Puerta o portón', 'La puerta o portón como estructura física: algo que se puede abrir, cerrar, custodiar o marcar. Por metonimia, el vocablo pasa del pasadizo a la hoja que lo cierra. En Éx 12:22-23, la sangre se aplica en los postes y el dintel de ''la puerta'' (la estructura, no la abertura). Gn 4:7 personifica al pecado agazapado ''a la puerta'', y Gn 6:16 describe la puerta que Noé pone en el arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129207, 'spa', 'Revelación iluminadora', 'En el Salmo 119:130, el salmista declara que la apertura de las palabras de Dios da luz. Este sentido abarca tanto la imagen física de desenrollar un pergamino como la realidad espiritual de la iluminación. El contexto enfatiza la revelación y el entendimiento que surgen cuando la palabra divina se hace accesible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129208, 'spa', 'Espadas desenvainadas', 'Usado figuradamente en el Salmo 55:21 para describir las palabras suaves pero hostiles de un falso amigo. El salmista contrasta el habla blanda y mantecosa con la malicia afilada que se esconde debajo, convirtiendo este término en un ejemplo vívido de la sabiduría bíblica sobre los peligros de la retórica engañosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129210, 'spa', 'Petajías (nombre propio)', 'Las cuatro ocurrencias se refieren a tres hombres distintos llamados Petajías. 1 Crónicas 24:16 registra la división sacerdotal; Esdras 10:23 y Nehemías 9:5 probablemente designan al mismo levita involucrado en la renovación del pacto; Nehemías 11:24 menciona a un judío al servicio de la administración persa. Las transcripciones de la Septuaginta (Φαθαια, Φεθεια) conservan el nombre con variaciones ortográficas menores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129211, 'spa', 'Persona simple o ingenua, sin experiencia, susceptible de ser persuadida tanto h', 'Persona simple o ingenua, sin experiencia, susceptible de ser persuadida tanto hacia la sabiduría como hacia la necedad. Proverbios presenta al פְּתִי como el joven oyente que debe elegir entre la Señora Sabiduría y la Señora Necedad (Pr 9:4, 16). El término se sitúa entre el sabio (חָכָם) y el necio (כְּסִיל), sugiriendo una ingenuidad redimible. El Salmo 19:7 afirma que el testimonio de Dios hace sabio al simple, mientras que el Salmo 116:6 muestra el cuidado divino por los sencillos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129222, 'spa', 'Ingenuidad moral', 'Aparece en Proverbios 1:22 en la pregunta retórica de la Sabiduría personificada: «¿Hasta cuándo, simples, amaréis la simpleza?» No se trata de falta de inteligencia, sino de la negativa o incapacidad de abrazar la sabiduría, lo cual deja a la persona expuesta a toda necedad que se le presente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129224, 'spa', 'Vestidura lujosa', 'Se encuentra en Isaías 3:24, dentro de un oráculo profético que enumera artículos de adorno suntuoso que serán reemplazados por señales de duelo. El término representa toda una clase de prendas importadas que marcaban estatus social, pero que resultarían inútiles en el día del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129225, 'spa', 'Simpleza seductora', 'Usado en Proverbios 9:13 para caracterizar a la Mujer Necedad, descrita con este término. Algunos sugieren que «seductora» o «tentadora» encaja mejor que «simpleza» en la personificación de la Necedad como figura adúltera. La evidencia multilingüe muestra a los traductores debatiéndose entre simplicidad moral y engaño activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129226, 'spa', 'Cordón, cuerda', 'Un cordón o cuerda: una soga torcida o ligadura usada para sujetar, atar o colgar objetos. Nueve de once apariciones corresponden a este sentido, abarcando el cordón azul sacerdotal (petil tekhelet) que asegura el pectoral (Éx 28:28, 37; 39:21, 31), el cordón personal de Judá dado como garantía (Gn 38:18, 25), la línea de medir de cordón de lino en Ezequiel 40:3 y el cordón de estopa de Jueces 16:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129229, 'spa', 'Hilo (hebra fina)', 'Un hilo: una hebra fina y delgada, distinguida del cordón más grueso por el contexto que enfatiza delicadeza o finura. Números 15:38 prescribe un petil tekhelet (''hilo de azul'') para colocar en el fleco de las vestiduras, donde la imagen es de una sola hebra visible entretejida en los tsitsit. Jueces 16:9 compara la ruptura de las ataduras de Sansón «como hilo de estopa» (petil ne''oret), subrayando la fragilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129235, 'spa', 'Torcer, luchar, ser astuto', 'Torcer, luchar o actuar tortuosamente. En el Nifal denota lucha o forcejeo (Gn 30:8, la designación de Neftalí por Raquel) y perversidad moral: el consejo «retorcido» del astuto (Job 5:13) y el habla «tortuosa y torcida» (Pr 8:8). En el Hitpael describe la acción recíproca de Dios: con el perverso se muestra sagaz (Sal 18:26; 2 Sam 22:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129236, 'spa', 'Perverso y torcido', 'Aparece en Deuteronomio 32:5, donde Moisés describe a Israel como «generación torcida y perversa». No se trata de un simple error, sino de una deformación del alma, un rechazo a ser recto cuando Dios mismo es descrito como la Roca cuya obra es perfecta. El término connota corrupción profunda y obstinada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129237, 'spa', 'Ciudad egipcia', 'Mencionada en Éxodo 1:11 como uno de los centros de abastecimiento construidos mediante trabajo forzado. La ciudad representa el aparato de opresión bajo el cual Israel gemía antes de que Dios oyera su clamor y levantara a Moisés como libertador de su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129238, 'spa', 'Cobra o áspid venenoso', 'El peten (פֶּתֶן), serpiente venenosa identificada como la cobra o áspid mortal, usada exclusivamente en poesía y profecía como símbolo de peligro letal. Dt 32:33 habla del veneno de los petanim; Job 20:14, 16 compara el pecado oculto con veneno de cobra; Sal 58:4 describe al peten sordo que resiste al encantador; Sal 91:13 promete que el justo lo pisará; e Is 11:8 imagina a un niño jugando junto a su cueva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129243, 'spa', 'De repente, súbitamente', 'De repente, en un instante — marca una acción o evento como abrupto e imprevisto. En Números 35:22 califica un empujón accidental (''en repentino'', es decir, sin premeditación). Emparejado con פִּתְאֹם en Números 6:9 e Isaías 29:5 para fuerza enfática (''muy de repente''). En Proverbios 6:15 y 29:1 describe el quiebre veloz e irreversible del insensato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129248, 'spa', 'Interpretar sueños/visiones', 'Interpretar sueños o visiones, declarando su significado oculto. Cognado del arameo peshar (''disolver, interpretar''), evocando la imagen de desentrañar algo oscuro. Todas las apariciones se encuentran dentro del ciclo de José: los sueños del copero y el panadero (Gn 40:8, 16, 22) y los sueños de Faraón (Gn 41:8, 12, 13, 15). La evidencia multilingüe es notablemente uniforme: español ''interpretó/intérprete''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129254, 'spa', 'Interpretación de sueños', 'La interpretación o significado revelado de un sueño. Circunscrito enteramente al ciclo de José (Gn 40:5, 8, 12, 18; 41:11), el sustantivo aparece en formas singular y plural. Todas las lenguas meta lo traducen con un término de revelación cognitiva (esp. «interpretación», al. «Deutung»), confirmando un sentido único y preciso: la explicación autoritativa que desvela el mensaje profético de un sueño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129255, 'spa', 'Alto Egipto', 'Topónimo geográfico que designa el Alto Egipto. Sus cinco apariciones se dan en contextos proféticos (Is 11:11; Jer 44:1, 15; Ez 29:14; 30:14), siempre emparejado con mitsráyim para especificar la región meridional del Nilo. Las traducciones transliteran uniformemente el nombre (esp. «Patros», fr. «Pathros»), reflejando su condición de topónimo reconocido del corazón de Egipto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129257, 'spa', 'Desmenuzar pan', 'Forma verbal que instruye cómo preparar la ofrenda de cereal en Levítico 2:6. La acción consiste en partir pan u obleas en fragmentos pequeños. Lenguas semíticas emparentadas confirman este sentido de triturar o desmenuzar en porciones, una acción culinaria y ritual común en el culto del antiguo Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129260, 'spa', 'Rebaño, ganado menor', 'Sustantivo colectivo para ganado menor que abarca tanto ovejas como cabras en un grupo unificado. Se usa para rebaños pastoriles literales (Gn 30:31), animales para el sacrificio (Gn 4:4) y riqueza en hatos (Gn 24:35). Se extiende metafóricamente para describir a Israel como rebaño de Dios bajo su cuidado pastoral (Sal 100:3; Ez 34). Las traducciones en francés alternan entre brebis y moutons, reflejando la lectura predominantemente ovina del colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129340, 'spa', 'Ciudad de Judá', 'Aparece en Miqueas 1:11 dentro de una serie de juegos de palabras proféticos sobre nombres de ciudades. La localidad funciona tanto como lugar real como recurso literario, ya que su nombre evoca los temas de salir o no poder hacerlo, encajando en la visión más amplia de Miqueas sobre el juicio que barre la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129341, 'spa', 'Descendencia, vástagos', 'Descendencia, vástagos — la progenie o prole de seres humanos. Nueve apariciones llevan este sentido, en paralelo regular con zera'' (''semilla/descendencia'') y banim (''hijos''). Isaías 48:19 y 44:3 emparejan tse''etsa''im con zera'' en promesas de posteridad abundante; Job 21:8 y 27:14 lo usan de los hijos de los impíos; Isaías 61:9 y 65:23 vislumbran a los descendientes de los redimidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129343, 'spa', 'Producto, brotes (de la tierra)', 'Producto, brotes — el rendimiento o la vegetación de la tierra. Isaías 34:1 convoca al «mundo y todo lo que brota de él» a escuchar el juicio, e Isaías 42:5 describe a Dios como quien da aliento a los que están sobre la tierra junto con su producto. El árabe ''nabatatuha'' (''sus plantas/vegetación'') en ambos pasajes distingue este sentido del de descendencia humana, apuntando a un referente botánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129351, 'spa', 'Reptil impuro', 'Figura en Levítico 11:29 entre las criaturas que se arrastran consideradas impuras. La lista es taxonómicamente compleja, pero su intención es práctica: definir los límites de pureza ritual y dieta que distinguían a Israel de las naciones circundantes. El término señala un reptil terrestre de tamaño considerable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129352, 'spa', 'Servir, cumplir un deber o ministrar, especialmente en contexto religioso o cult', 'Servir, cumplir un deber o ministrar, especialmente en contexto religioso o cultual. Las mujeres que servían a la entrada del Tabernáculo de Reunión (Éx 38:8; 1 S 2:22) y los levitas que entran en servicio a los veinticinco años (Nm 4:23; 8:24) emplean este verbo. El español servir, el hindi seva karna y el alemán dienen reflejan la naturaleza pacífica y devocional de este sentido. La metáfora subyacente de servicio organizado vincula este uso con el sentido militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129353, 'spa', 'Guerrear, combatir o participar en combate militar', 'Guerrear, combatir o participar en combate militar. El Qal se emplea cuando el ejército de Israel sale a la batalla contra Madián (Nm 31:7, 42), cuando las naciones asedian Jerusalén (Is 29:7-8) y cuando los ejércitos combaten contra Sion (Is 31:4). El español guerrear, el francés combattre, el hindi ladna, el árabe haraba y el suajili kupigana confirman el registro marcial. La forma participial צֹבְאִים funciona como sustantivo que designa a los que guerrean.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129356, 'spa', 'Alistar, reclutar o reunir tropas —la forma causativa Hifil que describe al ofic', 'Alistar, reclutar o reunir tropas —la forma causativa Hifil que describe al oficial que convoca al pueblo para el servicio militar. En 2 Reyes 25:19 y Jeremías 52:25, entre los llevados cautivos figura ''el oficial que alistaba al pueblo de la tierra'', un cargo administrativo militar específico. El español alistar, el hindi bharti karna y el alemán mustern captan la función organizativa de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129364, 'spa', 'Querer, desear (arameo)', 'Querer, desear o complacerse, expresando volición deliberada o propósito soberano. En el arameo de Daniel, este verbo aparece tanto para la voluntad incontestable de Dios (''Él hace según su voluntad entre el ejército del cielo,'' Dn 4:35) como para la prerrogativa real (''a quien quería mataba, y a quien quería dejaba con vida,'' Dn 5:19). El cognado siríaco confirma el sentido básico de inclinación o deseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129368, 'spa', 'Ejércitos divinos', 'En 2 Reyes 19:31, la expresión «el celo del SEÑOR de los Ejércitos» (צְבָאוֹת) fundamenta la promesa de liberación frente a Asiria. Este título proclama la autoridad incomparable de Dios y su capacidad de actuar decisivamente en la historia, siendo consuelo para los asediados y advertencia para los enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129370, 'spa', 'Ejército, hueste (general)', 'Ejército, hueste o fuerza militar organizada en sentido amplio (192 ocurrencias): cubre tanto ejércitos humanos reunidos para la batalla como la hueste celestial —fuerzas angélicas o cuerpos celestes bajo el mando de Dios—. En ''YHWH de los ejércitos'', el término alcanza alcance cósmico. Las traducciones convergen en ''ejército'' como glosa primaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129384, 'spa', 'Servicio forzado, deber', 'Servicio duro u obligatorio, trabajo forzado, período de deber asignado. Aparece en pasajes como Job 14:14 (''todos los días de mi servicio esperaré'') e Is 40:2 (''su milicia ha terminado''). Los períodos de servicio levítico en Nm 4:23 y 8:24-25 también portan este matiz de deber acotado y prescrito. El español servicio y el alemán Dienst capturan este sentido no combativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129385, 'spa', 'Guerra, campaña militar', 'Guerra como actividad o campaña militar. Más que la fuerza reunida, este sentido apunta al acto de guerrear. Jos 22:12 y 22:33 lo emplean para la perspectiva de ir a la guerra, y Job 7:1 enmarca la existencia terrenal como una campaña. El español guerra y el alemán Krieg desplazan el foco del personal al acontecimiento bélico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129412, 'spa', 'Ejércitos, huestes (de YHWH)', 'Sustantivo plural que significa ''huestes'' o ''ejércitos'', usado casi exclusivamente en el epíteto divino YHWH Tseva''ot (''Señor de los Ejércitos''). El título aparece por primera vez en el contexto del santuario de Siló (1 S 1:3) y se convierte en el nombre profético dominante para Dios, especialmente en Isaías, Jeremías y los profetas postexílicos. Ya se refieran las ''huestes'' a los ejércitos de Israel, los ángeles celestiales (Sal 103:21; 148:2) o las estrellas, el título proclama la soberanía universal de YHWH.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129416, 'spa', 'Zeboiim (topónimo)', 'Nombre propio que identifica una de las cinco ciudades de la llanura aliadas con Sodoma, Gomorra y Admá. En la Tabla de las Naciones marca la extensión del territorio cananeo (Gn 10:19). Su rey participó en la batalla del Valle de Sidim (Gn 14:2, 8). Deuteronomio 29:23 emplea su destrucción como advertencia del pacto. De manera memorable, Oseas 11:8 la empareja con Admá en la agonizante deliberación divina sobre el juicio contra Efraín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129421, 'spa', 'Nombre genealógico', 'Mencionado en 1 Crónicas 4:8 como parte del linaje de Judá. El hebreo conserva el artículo definido (הַצֹּבֵבָה), lo cual podría indicar una designación de clan o familia. Las variaciones en la Septuaginta sugieren incertidumbre escribal, pero el nombre contribuye al relato exhaustivo del Cronista sobre la estructura e identidad tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129423, 'spa', 'Hinchazón por maldición', 'Aparece en Números 5:21 describiendo la consecuencia física de la maldición: el cuerpo de la mujer se hinchará. No se trata de algo metafórico, sino de una condición literal y observable que confirmaría públicamente la culpa en una sociedad sin herramientas forenses modernas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129424, 'spa', 'Asunto o distracción', 'Empleado en Daniel 6:17 (6:18 en versiones españolas) para indicar que ninguna distracción ni entretenimiento fue llevado ante el rey insomne. El español «propósito» y el francés «nourriture» (alimento) muestran desacuerdo traductivo, reflejando la flexibilidad semántica del término. El contexto sugiere cualquier cosa que pudiera ocupar o consolar al rey —comida, música, compañía— todo rechazado en su angustia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129425, 'spa', 'Moteado o manchado', 'Jeremías 12:9 lo usa para describir un ave de rapiña que, por su coloración inusual, es atacada por otras aves. El español «manchada» resalta el patrón irregular. La imagen profética parece representar a Israel o Judá como algo conspicuo y por tanto vulnerable: su propia distinción los convierte en blanco en vez de protegerlos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129426, 'spa', 'Entregar o alcanzar', 'Describe la acción de Booz en Rut 2:14 cuando ofrece grano tostado a Rut. El español «le pasó» y el inglés «he handed» capturan la transferencia. Este sencillo acto está cargado de significado narrativo: Booz reconoce a Rut, provee para ella e inicia el proceso de redención que culminará en matrimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129427, 'spa', 'Belleza o esplendor abstracto', 'Belleza o esplendor abstracto: la cualidad estética de gloria o hermosura aplicada a personas, lugares u objetos. La ''flor marchita de su gloriosa hermosura'' en Isaías 28:1, 4 describe la corona de Samaria; la ''corona de hermosura'' en Isaías 28:5 pertenece a Yahvé mismo. Es el sentido más frecuente, con nueve ocurrencias en cadenas constructas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129428, 'spa', 'Gloria u honor', 'Gloria u honor: tres ocurrencias (Is 24:16; Ez 25:9, 26:20) donde el énfasis recae en el estatus exaltado y el prestigio más que en la belleza visual. Cuando Isaías escucha ''Gloria al Justo'' (Is 24:16), צְבִי lleva el peso del honor público, no de la mera atracción estética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129430, 'spa', 'Ornamento o adorno', 'Ornamento o adorno: cuatro ocurrencias donde צְבִי pasa de cualidad abstracta a algo más cercano a un emblema concreto o posesión preciada. Babilonia es ''la hermosura de los reinos'' (Is 13:19); la tierra de Israel es ''herencia de hermosura'' entre las naciones (Jer 3:19; Ez 20:6, 15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129434, 'spa', 'Gacela (sentido zoológico)', 'Gacela (sentido zoológico): el sentido concreto del animal, que aparece en el problemático pasaje de 2 Samuel 1:19. El lamento de David explota el doble significado: Saúl y Jonatán son tanto la ''hermosura'' como la ''gacela'' de Israel — gráciles, veloces y ahora caídos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129438, 'spa', 'La Tierra Hermosa (epíteto)', 'La Tierra Hermosa (epíteto): designación titular cristalizada para la Tierra de Israel en Daniel 8:9, donde el ''cuerno pequeño'' crece hacia ''la Hermosa [Tierra].'' No es una mera descripción adjetival sino un título fijo, casi un nombre propio, para la Tierra Prometida en el discurso apocalíptico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129439, 'spa', 'La gacela (צְבִי como sustantivo animal), un antílope veloz y grácil originario ', 'La gacela (צְבִי como sustantivo animal), un antílope veloz y grácil originario del Levante. Las glosas interlingüísticas coinciden perfectamente: español ''gacela'', francés ''gazelle'', alemán ''Gazelle'', confirmando el referente zoológico. El término opera en tres registros semánticos: la ley dietética, donde es caza limpia (Dt 12:15; 14:5); el símil militar, donde figura como imagen de velocidad extraordinaria (2 S 2:18; 1 Cr 12:8); y la poesía amorosa del Cantar de los Cantares, donde encarna belleza y gracia (Cnt 2:9, 17; 8:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129448, 'spa', 'Nombre propio benjaminita', 'Mencionado en 1 Crónicas 8:9 dentro de la genealogía de Benjamín. La escasa variación multilingüe (la mayoría preserva la forma hebrea) indica un tratamiento estándar de nombre propio. Las genealogías de Crónicas sirven para anclar la identidad y continuidad tribal, especialmente importantes para las comunidades que se reconstruían tras el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129451, 'spa', 'Ser empapado con rocío', 'Ser empapado o mojado, específicamente con rocío. Las cinco apariciones se agrupan en la narrativa de la locura de Nabucodonosor (Dn 4:15, 23, 25, 33; 5:21), siempre en colocación con ''rocío del cielo'' (טַל שְׁמַיָּא). Las glosas multilingües convergen en vocabulario de contacto líquido (esp. ''mojado'', fra. ''tremper'', ale. ''benetzen''), representando uniformemente el empapamiento involuntario como signo de la degradación del rey a condición bestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129452, 'spa', 'Tela teñida, botín', 'El Cántico de Débora retrata vívidamente los despojos anticipados: ''tela teñida, obra bordada'' como premios de guerra. Las tres instancias se agrupan en Jueces 5:30, construyendo ironía dramática—el tesoro esperado que nunca llegará. La traducción translingüística uniforme (''vestiduras/tela teñida'') confirma que esto se refiere a tela tratada con tintes valiosos, señal de riqueza y estatus en la cultura del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129453, 'spa', 'Zibeón (nombre propio)', 'Nombre propio que identifica a un jefe de clan horeo de las tierras altas de Seir, presente en las genealogías de Esaú y en el registro de los descendientes de Seir. Aparece como hijo de Seir el horeo (Gn 36:20, 29; 1 Cr 1:38) y también como abuelo de la esposa de Esaú, Oholibama, a través de su hija o nieta Aná (Gn 36:2, 14). El descubrimiento de fuentes termales por parte de su hijo Aná (Gn 36:24) constituye el único detalle narrativo asociado a este linaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129459, 'spa', 'Amontonar, almacenar', 'Apilar, amontonar o almacenar en gran cantidad, con énfasis en el volumen descomunal de lo acumulado. José almacenó grano sin medida durante los años de abundancia (Gn 41:35, 49). Los israelitas amontonaron ranas muertas en montones fétidos (Éx 8:14). Habacuc 1:10 habla de amontonar polvo contra una ciudad fortificada. En contextos sapienciales, el verbo adquiere un matiz irónico: los impíos amontonan plata como polvo (Job 27:16; Zac 9:3), pero otros heredarán sus bienes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129466, 'spa', 'Montones o pilas', 'En 2 Reyes 10:8, los mensajeros informan que las cabezas de los hijos del rey han sido traídas y colocadas en dos montones a la puerta de la ciudad. El español «montones» y el inglés «heaps» subrayan la exhibición brutal. Se trata de un espectáculo público como mensaje político: el antiguo régimen ha sido completamente destruido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129467, 'spa', 'Manojos de grano', 'Rut 2:16 describe la instrucción de Booz de dejar que Rut espigue de los manojos e incluso sacar grano para ella. No se trata de tallos sueltos, sino de gavillas reunidas y atadas. La orden de Booz de soltar parte del grano para Rut constituye un acto de generosidad sutil pero significativo que supera el mínimo exigido por la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129468, 'spa', 'Funciona como relator espacial con el significado de ''al lado de, junto a'', indi', 'Funciona como relator espacial con el significado de ''al lado de, junto a'', indicando ubicación respecto de otro objeto o persona. Este uso preposicional aparece cuando el rollo de la Torá se coloca junto al arca de la alianza (Dt 31:26) y cuando Rut se sienta al lado de los segadores (Rt 2:14). Las traducciones al francés y al alemán emplean consistentemente locuciones relacionales como ''du côté de'' y ''auf Seite von''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129469, 'spa', 'El costado o flanco físico de un cuerpo humano o animal, incluida la zona de las', 'El costado o flanco físico de un cuerpo humano o animal, incluida la zona de las costillas. Se ordena a Ezequiel acostarse sobre su costado como señal profética (Ez 4:4, 6), y el Salmo 91:7 promete protección aun cuando mil caigan a tu lado. El ganado de Ezequiel 34:21 empuja con el flanco y el hombro. El español distingue este uso con ''costado'' frente al más abstracto ''lado''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129470, 'spa', 'Designa la cara lateral, el borde o el flanco de un edificio, altar, recipiente ', 'Designa la cara lateral, el borde o el flanco de un edificio, altar, recipiente o elemento geográfico. El arca tiene una puerta en su lado (Gn 6:16) y el candelabro tiene ramas que se extienden desde sus lados (Éx 25:32). A menudo aparece en plural para referirse a las dos caras opuestas de una estructura. El español ''de sus lados'' y el francés ''côtés de'' captan bien este sentido arquitectónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129471, 'spa', 'Se emplea en el vívido modismo donde pueblos hostiles se convierten en ''espinas ', 'Se emplea en el vívido modismo donde pueblos hostiles se convierten en ''espinas en vuestros costados'' (Nm 33:55; Jos 23:13; Jue 2:3), expresando una aflicción persistente y dolorosa. La imagen combina el sentido corporal vulnerable con la penetración agresiva, creando una figura de hostigamiento continuo por parte de enemigos no conquistados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129487, 'spa', 'Interrogación de veracidad', 'Daniel 3:14 abre con esta pregunta del rey, que busca verificar el informe de que Sadrac, Mesac y Abednego se han negado a adorar la imagen de oro. La expresión establece la confrontación entre el poder real y la fidelidad religiosa, con la vida y la muerte en juego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129490, 'spa', 'Desolación urbana', 'Sofonías 3:6 emplea este verbo para describir el destino de las ciudades bajo el juicio divino: quedan asoladas, sus calles vacías. El verbo no retrata un simple daño, sino desolación absoluta: la vida y la habitación han sido eliminadas, dejando solo escombros y silencio como testimonio del castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129491, 'spa', 'Nombre propio Sadoc (צָדוֹק, ''justo''), que designa principalmente al sumo sacerd', 'Nombre propio Sadoc (צָדוֹק, ''justo''), que designa principalmente al sumo sacerdote que sirvió bajo David y Salomón y fundó la dinastía sacerdotal dominante. La visión de Ezequiel reserva el santuario interior para los ''hijos de Sadoc'' que permanecieron fieles (Ez 44:15). El nombre también aparece para un sacerdote de la época del Cronista (1 Cr 5:38), el suegro de Uzías (2 R 15:33) y constructores del muro de Nehemías (Neh 3:4, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129498, 'spa', 'Topónimo en Neftalí', 'Mencionada en Josué 19:35 como una de las ciudades fortificadas de Neftalí. El hebreo incluye el artículo definido (הַצִּדִּים), lo que posiblemente indica que era bien conocida en su tiempo. La lista sitúa la herencia de Neftalí en los confines septentrionales de Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129499, 'spa', 'Persona justa (sustantivado)', 'El uso abrumadoramente dominante: tsaddiq como sustantivo o adjetivo sustantivado que describe a un individuo o grupo moralmente recto. Desde Noé caminando en integridad (Gn 6:9) hasta la confianza del salmista en que el justo florecerá como palmera (Sal 92:12), este sentido permea la literatura sapiencial y narrativa por igual. El español justo, el francés juste y el alemán Gerechte convergen en esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129505, 'spa', 'Justo (atributo divino)', 'Cuando tsaddiq se predica de Dios o se emplea como título divino, pasa de describir la virtud humana a proclamar la perfección moral esencial de YHWH. La confesión de Faraón ''YHWH es el justo'' (Éx 9:27) y la declaración del salmista ''justo eres tú, oh Señor'' (Sal 119:137) usan el mismo lexema pero en un registro claramente teológico. Las traducciones coreanas emplean honoríficos especiales que marcan esta diferencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129513, 'spa', 'Justo (nación o comunidad)', 'Aplicado atributivamente a una entidad colectiva: una nación o ciudad caracterizada por la justicia. Is 26:2 invita a la ''nación justa'' que guarda la fidelidad a entrar por las puertas, y Gn 20:4 presenta a Abimelec apelando a Dios como quien no destruiría una ''nación justa''. El árabe usa la forma femenina بَارَّةً y el suajili ''lenye haki'', ambos reflejando la justicia como cualidad comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129518, 'spa', 'Correcto, con razón', 'Sentido forense en el que tsaddiq significa no ''moralmente virtuoso'' sino ''que tiene una causa justa'' o ''que está en lo correcto''. Is 41:26 pregunta quién lo declaró desde el principio, ''para que digamos: tiene razón''. El hindi सही (sahī, correcto) y el suajili Sahihi (preciso) eligen vocablos del ámbito de la exactitud fáctica antes que del carácter moral, revelando este matiz judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129520, 'spa', 'Sentido estativo del Qal', 'Sentido estativo del Qal: ser justo, tener razón, tener una causa justa. Es el significado raíz: la condición moral o legal de una persona como correcta ante Dios o el juicio humano. Tamar ''es más justa que yo'' (Gn 38:26); ''¿cómo puede un mortal ser justo ante Dios?'' (Job 4:17; 9:2). En Ezequiel 16:52 incluso Sodoma resulta ''más justa'' en comparación. El árabe sadaqa (''decir la verdad'') conserva la noción de rectitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129523, 'spa', 'Sentido declarativo-forense del Hifil', 'Sentido declarativo-forense del Hifil: declarar justo, justificar, absolver o vindicar en un proceso legal. Es el sentido de tribunal: un juez pronunciando el veredicto de ''justo''. Éxodo 23:7 prohíbe absolver al culpable; Deuteronomio 25:1 prescribe que los jueces ''justificarán al justo y condenarán al impío''. Salomón ruega que Dios ''justifique al justo'' en el templo (1 R 8:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129531, 'spa', 'Sentido intensivo-declarativo del Piel', 'Sentido intensivo-declarativo del Piel: justificar, vindicar o declarar justo con fuerza enfática o iterativa. Job 32:2 critica a Job por ''justificarse a sí mismo'' en lugar de a Dios; Jeremías 3:11 declara que la infiel Israel se ha ''justificado'' más que la traidora Judá; Ezequiel 16:51-52 acusa a Jerusalén de hacer ''parecer justas'' a sus hermanas en comparación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129541, 'spa', 'Sentido participial del Hifil en Daniel 12', 'Sentido participial del Hifil en Daniel 12:3: ''los que conducen a muchos a la justicia'', usando la raíz causativa para expresar guiar o encaminar a otros hacia un estado de rectitud. Esto va más allá de la mera declaración forense y entra en la transformación moral activa de los demás. El español ''los que hacen justos'' capta este sentido causativo-educativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129544, 'spa', 'Hitpael reflexivo en Génesis 44', 'Hitpael reflexivo en Génesis 44:16: ''¿cómo nos justificaremos?'', la angustiada pregunta retórica de Judá ante José al encontrarse la copa en el saco de Benjamín. La raíz reflexiva significa exculparse, presentar una autodefensa. El español ''justificarnos'' y el alemán ''uns rechtfertigen'' marcan lo reflexivo, y el contexto deja claro que no se trata de reclamar inocencia sino de desesperar de cualquier defensa posible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129546, 'spa', 'Nifal pasivo en Daniel 8', 'Nifal pasivo en Daniel 8:14: ''el santuario será vindicado/restituido a su estado legítimo''. Esta única aparición usa la pasiva para describir el santuario siendo restaurado o purificado tras la profanación. El español ''será justificado'' y el patrón multilingüe de formas pasivas confirman una lectura de vindicación pasiva, aunque el matiz exacto —purificación, vindicación o restauración— ha sido debatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129554, 'spa', 'Justicia, rectitud (general)', 'La cualidad moral abstracta de ser recto, justo o íntegro en su sentido más amplio, que abarca la justicia salvífica de Dios (Sal 4:2; Is 41:10), la equidad judicial (Dt 1:16), las normas comerciales honestas (Lv 19:36) y el carácter recto del rey ideal (Is 32:1). Es el sentido dominante, del cual los demás se derivan como especializaciones contextuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129564, 'spa', 'Justo (uso predicativo)', 'Uso predicativo-adjetival donde tsedheq califica un sustantivo como ''justo'' o ''recto'': ''juicio justo'' (Dt 16:18), ''pesa cabal y justa'' (Dt 25:15). El español justa, el alemán gerecht y el hindi सीधा (recto, derecho) adoptan formas adjetivales, confirmando que en estos pasajes el vocablo funciona como modificador que describe la cualidad de la cosa, no como sustantivo abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129579, 'spa', 'Justicia activa', 'Daniel 4:27 emplea este término en el consejo de Daniel al rey: «Redime tus pecados con justicia». No se trata de mera pureza ritual, sino de justicia y misericordia activas, la evidencia tangible de un corazón transformado y un gobierno reformado que se ocupa de los más necesitados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129580, 'spa', 'Justicia, rectitud moral', 'La cualidad moral abstracta de la justicia: conformidad con la norma divina de rectitud, fidelidad pactual e integridad ética, en 145 de 159 ocurrencias. Abarca tanto la justicia divina salvífica (Sal 24:5; Is 45:8; 46:13) como la justicia acreditada a la fe de Abram (Gn 15:6), la justicia real ejecutada junto con el mishpat (2 S 8:15; Is 9:7) y la rectitud exigida a cada creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129591, 'spa', 'Actos de justicia', 'La forma plural tsidqot designa actos concretos de justicia, obras salvíficas o actos de vindicación: 13 ocurrencias donde la justicia pasa de cualidad a acontecimiento. Las ''justicias del Señor'' celebradas en el cántico de Débora (Jue 5:11) y el discurso de despedida de Samuel (1 S 12:7) relatan intervenciones históricas específicas. Is 64:6 invierte el patrón: incluso nuestras tsidqot son como vestiduras inmundas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129609, 'spa', 'Derecho legítimo', 'Una sola ocurrencia en Neh 2:20 donde tsedaqah aparece como declaración de derecho legítimo o pretensión jurídica: Nehemías afirma que ciertos adversarios no tienen ''parte, ni derecho (tsedaqah), ni memorial en Jerusalén''. Aquí el vocablo funciona más como ''derecho legal'' o ''participación legítima'' que como rectitud moral propiamente dicha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129626, 'spa', 'Nombre teofórico que significa ''Yahvé es mi justicia,'' referido principalmente a', 'Nombre teofórico que significa ''Yahvé es mi justicia,'' referido principalmente al último rey de Judá (originalmente Matanías, renombrado por Nabucodonosor, 2 R 24:17), cuyo reinado terminó con la caída catastrófica de Jerusalén (586 a.C.). El nombre también designa a un falso profeta que abofeteó a Micaías (1 R 22:24) y a otro condenado por Jeremías (Jer 29:21-22). Todas las lenguas lo preservan fonéticamente: español Sedequías, francés Sédécias, alemán Zedekia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129634, 'spa', 'Bronce pulido', 'Esdras 8:27 menciona «bronce reluciente» o «bronce pulido», describiendo vasijas valiosas. El término «pulido» capta la calidad del acabado. No es metal ordinario, sino tesoros cuidadosamente preparados para uso sagrado, cuyo brillo simboliza tanto el valor material como la honra debida a la casa de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129635, 'spa', 'Amarillo (diagnóstico)', 'Los tres usos aparecen en Levítico 13:30-36, el manual sacerdotal para diagnosticar צָרַעַת (a menudo traducido como ''lepra''). Cabello amarillo en una mancha escamosa indica contaminación, contrastando con el esperado cabello negro. La evidencia multilingüe muestra acuerdo universal sobre el término básico de color, con algunos añadiendo el artículo definido (''el amarillo'' vs. solo ''amarillo''), pero todos reconociendo esto como un marcador diagnóstico de enfermedad cutánea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129636, 'spa', 'Relinchar triunfante', 'Jeremías 50:11 se burla de Babilonia: os regocijáis y exultáis como caballos que relinchan. El contexto es de juicio: quienes relincharon en triunfo sobre Judá serán ellos mismos pisoteados. El verbo sugiere pasión o gozo descontrolado, y la falta de moderación de los vencedores ahora se cuenta en su contra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129637, 'spa', 'Clamar de gozo', 'Gritar, clamar de gozo o exultar con un grito agudo y penetrante; sentido dominante que abarca seis ocurrencias. Aparece en llamados proféticos a la adoración (Is 12:6; 54:1), un clamor de angustia (Is 10:30), alabanza gozosa (Is 24:14), celebración (Est 8:15) y un grito triunfante (Jer 31:7). La imagen central es la de un sonido estridente e irreprimible que brota de una emoción intensa, ya sea gozo, gratitud o esperanza restaurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129641, 'spa', 'Relinchar (caballos)', 'Relinchar, específicamente el sonido que producen los caballos, usado tanto literalmente de sementales como metafóricamente para describir comportamiento lujurioso o arrogante. Jeremías 5:8 compara a hombres adúlteros con sementales bien alimentados que «relinchan» tras las esposas de sus vecinos, y Jeremías 50:11 aplica la imagen a los saqueadores babilónicos que «relinchan» como sementales en su soberbia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129644, 'spa', 'Hacer brillar', 'El Salmo 104:15 describe a Dios dando aceite para hacer brillar el rostro, como parte de la provisión de la creación para el florecimiento humano. La expresión «hacer brillar» enfatiza la acción causativa. Más que cosmética, es la radiancia visible de una vida bendecida, la piel que resplandece con la salud proveniente de los buenos dones de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129645, 'spa', 'Prensar aceite', 'Job 24:11 describe a trabajadores que prensan aceite entre las hileras pero permanecen sedientos. El verbo es tanto literal (el trabajo de producción de aceite) como simbólico (la amarga ironía de producir abundancia mientras se sufre privación personalmente), una imagen vívida de la injusticia social que denuncia la explotación del obrero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129646, 'spa', 'Sustantivo para el mediodía', 'Sustantivo para el mediodía. Usado con preposiciones como marcador temporal: בַּצָּהֳרַיִם ''al mediodía'' (Gén 43:16; 1 Re 18:27), עַד־הַצָּהֳרַיִם ''hasta el mediodía'' (1 Re 18:26). Connota vulnerabilidad — andar a tientas al mediodía significa ceguera (Deut 28:29); atacar al mediodía señala sorpresa (Jer 6:4). Figurativamente representa vindicación y bendición: el justo resplandecerá como el mediodía (Sal 37:6; Isa 58:10). Las traducciones convergen: español ''mediodía,'' francés ''midi,'' alemán ''Mittag.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129653, 'spa', 'Techo o tragaluz', 'Génesis 6:16 ordena a Noé construir este elemento para el arca, completándolo a un codo de distancia. Ya sea techo, tragaluz o ventana, su función es proveer luz y aire dentro de la nave sellada, algo esencial para el viaje de un año. La tradición lo interpreta frecuentemente como ventana, aunque el significado exacto permanece debatido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129654, 'spa', 'Precepto, mandato', 'Un precepto, mandato o directiva, que aparece principalmente en Isaías 28:10, 13 dentro de la fórmula repetitiva tsav la-tsav (''mandato sobre mandato''), la cual puede ser un resumen genuino de la instrucción profética o una imitación burlona de la enseñanza insistente de Isaías. Oseas 5:11 lo emplea para una ordenanza que Efraín siguió voluntariamente. El paralelo con qav la-qav (''línea sobre línea'') sugiere una instrucción metódica y reglada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129656, 'spa', 'Inmundo, contaminado', 'Emergen dos contextos distintos: las amenazas vulgares del Rabsaces durante el asedio en 2 Reyes y la visión de purificación sacerdotal de Zacarías. Las glosas multilingües oscilan entre eufemismo y literalismo—algunas marcan ''excremento'' con corchetes, otras usan términos generales como ''inmundo'' o ''sucio''. En Zacarías, las vestiduras inmundas representan el estado moral de Israel; su remoción ilustra el perdón divino. La raíz significa contaminación profunda, no simple suciedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129657, 'spa', 'Inmundicia y excremento', 'Proverbios 30:12 usa inmundicia metafóricamente para la impureza moral (''no lavada de su inmundicia''). Isaías 4:4 la emplea de modo similar para la corrupción moral de Jerusalén que Dios lavará. Isaías 28:8 describe suciedad literal (mesas llenas de vómito). 2 Reyes 18:27 e Isaías 36:12 se refieren a comer el propio excremento durante un asedio; aunque el Ketiv usa otro término (חֶרֶא), el Qeré lee צֹאָתָם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129658, 'spa', 'Cuello adornado o sometido', 'Daniel 5:7, 16 y 29 mencionan la colocación de una cadena de oro alrededor del cuello de quien interprete la escritura misteriosa, como parte de la recompensa (manto púrpura, cadena de oro, tercer gobernante). Oseas 10:11 usa la forma hebrea para referirse al «hermoso cuello» de Efraín que será puesto bajo yugo, pasando del honor a la sujeción. El cuello simboliza dignidad cuando es adornado y sumisión cuando es yugado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129659, 'spa', 'El cuello anatómico, la parte del cuerpo que conecta la cabeza con el torso, apa', 'El cuello anatómico, la parte del cuerpo que conecta la cabeza con el torso, aparece en tres agrupaciones contextuales principales: (1) el modismo de abrazo nafal al-tsavvar, ''caer sobre el cuello'', que expresa intensa emoción de reencuentro (Gn 33:4; 45:14; 46:29); (2) adorno y autoridad: cadenas de oro (Gn 41:42; Dn 5:7, 16, 29) y joyas (Cnt 1:10; 4:4, 9; Pr 1:9; 3:3, 22); (3) sometimiento: el cuello soporta literalmente el yugo de la servidumbre (Dt 28:48; Jer 28:14) y la espada del enemigo (Job 16:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129676, 'spa', 'Collar ornamental', 'Cantares 4:9 habla poéticamente del poder de una sola joya de los collares de la amada. La expresión «de tu cuello» sitúa la imagen en el lenguaje del cortejo y la belleza. El collar es adorno literal y a la vez metáfora del encanto irresistible de la mujer, cuya presencia cautiva sin remedio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129677, 'spa', 'Soba (ciudad-estado aramea)', 'Una ciudad-estado aramea en el valle de la Becá, entre Hamat y Damasco, gobernada por Hadad-ezer. David derrotó a Hadad-ezer junto al Éufrates (2 S 8:3-5, 12), los amonitas contrataron tropas de Soba (2 S 10:6, 8) y Saúl combatió contra sus reyes (1 S 14:47). Rezón huyó después a Damasco (1 R 11:23-24); Salomón conquistó Hamat-Soba (2 Cr 8:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129680, 'spa', 'Atrapar almas (Piel)', 'Atrapar almas (Piel): atrapar o enredar personas, particularmente sus almas, con connotaciones de trampa engañosa mediante hechicería o falsa profecía. Ezequiel 13:18-20 contiene las cuatro ocurrencias, donde falsas profetisas cosen bandas mágicas y ''cazan almas'' — la frase repetida נַפְשׁוֹת תְּצוֹדֵדְנָה. Dios declara que arrancará sus velos y liberará las almas que cazan ''como aves.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129681, 'spa', 'Cazar animales (Qal literal)', 'Cazar animales (Qal literal): cazar animales silvestres para alimento o deporte, la persecución física de la presa. Génesis 27 es la narrativa definitoria: Isaac ordena a Esaú ''sal al campo y cázame caza'' (Gn 27:3, 5), y el anciano padre luego pregunta ''¿quién fue el que cazó caza?'' (Gn 27:33). Levítico 17:13 regula la sangre de la caza cobrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129684, 'spa', 'Perseguir o acechar a una persona (Qal figurativo)', 'Perseguir o acechar a una persona (Qal figurativo): perseguir, acechar o cazar a alguien como si fuera presa. Lamentaciones 3:52 ofrece la imagen más conmovedora — ''me cazaron sin cesar como a un ave'' — y Lamentaciones 4:18 registra a enemigos acechando por las calles. Job 10:16 presenta a Dios cazándolo como un león, y el Salmo 140:12 advierte que el mal perseguirá al hombre violento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129696, 'spa', 'Aprovisionarse para viaje', 'En Josué 9:12, los gabaonitas declaran: «Este pan tomamos como provisión de nuestras casas». El verbo capta el acto de asegurar suministros alimenticios. La ironía radica en que toda su historia es un ardid: el pan mohoso es un accesorio calculado en su engaño para lograr una alianza con Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129697, 'spa', 'Mandar, ordenar', 'El sentido abrumadoramente dominante: mandar, ordenar o imponer un encargo con autoridad. Cubre toda la gama de formas activas del Piel —desde Dios mandando a Adán (Gn 2:16) hasta Moisés ordenando a Israel (Dt 4:5) y reyes y funcionarios emitiendo directivas—. El árabe amara y el alemán befehlen/gebieten capturan el tono autoritativo esencial de este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129720, 'spa', 'Ser mandado (pasivo)', 'El Pual pasivo: ser mandado, recibir o estar bajo una orden. Solo 9 ocurrencias, pero de peso teológico, particularmente en instrucciones levíticas donde Aarón y sus hijos ''fueron mandados'' a realizar rituales específicos (Lv 8:35; 10:13). La pasiva desplaza el foco desde la autoridad que manda hacia quien recibe el encargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129784, 'spa', 'Designar, comisionar', 'Designar o comisionar a alguien para un cargo o tarea: un uso del Piel donde el énfasis se desplaza de la orden verbal a la designación posicional. En 1 S 25:30, Abigail habla de que YHWH designará a David como jefe sobre Israel; en 2 S 6:21, David declara que Dios lo eligió como gobernante. El árabe ''ayyina (''nombrar'') y el hindi niyukt karna (''designar'') seleccionan vocabulario específico de nombramiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129794, 'spa', 'Comandante (participio)', 'Participio sustantivado: el que manda, un comandante. Una sola ocurrencia en Is 55:4, donde la figura davídica es llamada ''líder y comandante de los pueblos''. El español gobernante y el alemán Gebieter (''el que manda'') nominalizan el verbo en un título de autoridad. El paso de la acción al nombre de agente es una función estándar del participio hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129807, 'spa', 'Enviar un mensaje', 'Enviar palabra o despachar órdenes: un uso del Piel donde el énfasis recae en la transmisión de un mensaje más que en el ejercicio directo de autoridad sobre un subordinado. En Gn 50:16, los hermanos de José ''mandaron decir'' (vayetsavvu), enviando un mensaje a través de intermediarios. El árabe arsalū (''enviaron'') y el alemán sie ließen sagen (''hicieron decir'') capturan la cualidad mediada y delegada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129814, 'spa', 'Gritar con júbilo', 'Isaías 42:11 convoca a los habitantes del desierto a gritar de gozo ante la salvación de Dios. El verbo sugiere volumen e intensidad: no es habla cortés sino un clamor exuberante, la clase de celebración que no puede contenerse, que da voz a la alegría por la obra redentora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129815, 'spa', 'Clamor de aflicción', 'Salmo 144:14 describe la bendición como ausencia de clamor en las calles, es decir, paz y seguridad. Isaías 24:11 retrata la angustia urbana: «clamor por el vino en las calles» durante el juicio. Jeremías 14:2 usa «clamor» para el duelo de Judá en la sequía, y Jeremías 46:12 profetiza que el grito de Egipto llenará la tierra al ser vencido. El término subraya el carácter público e intenso del lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129816, 'spa', 'Abismo oceánico', 'En Isaías 44:27, Dios dice al abismo: «¡Sécate!», como parte de una promesa de restauración. La expresión «al abismo» capta la inmensidad de esas aguas formidables. La palabra divina que seca las profundidades evoca tanto la creación como el éxodo, asegurando que ningún obstáculo supera los propósitos de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129817, 'spa', 'Abstenerse voluntariamente de comer, invariablemente en un contexto religioso de', 'Abstenerse voluntariamente de comer, invariablemente en un contexto religioso de duelo, contrición, intercesión o devoción. David ayuna por su hijo moribundo (2 S 12:16), Israel ayuna en Mizpa en arrepentimiento nacional (Jue 20:26; 1 S 7:6), y Zacarías 7:5 cuestiona la sinceridad del ayuno. Las traducciones multilingües convergen en este único acto devocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129832, 'spa', 'El acto u ocasión de abstenerse voluntariamente de alimento como disciplina reli', 'El acto u ocasión de abstenerse voluntariamente de alimento como disciplina religiosa. Proclamado públicamente por reyes o sacerdotes (1 Re 21:9, 12; 2 Cr 20:3; Joel 1:14; 2:15), o practicado en privado en el duelo y la petición (2 Sam 12:16; Dan 9:3; Neh 9:1). Zacarías 8:19 enumera cuatro ayunos calendáricos que conmemoran la caída de Jerusalén, profetizando su transformación en fiestas de gozo. Isaías 58:3-6 redefine el verdadero ayuno como justicia, misericordia y liberación, no mera aflicción corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129840, 'spa', 'Nombre propio: Zuar', 'Nombre propio del padre de Natanael, de la tribu de Isacar. Todas las apariciones emplean la frase estereotipada ''Natanael hijo de Zuar'' en listas censales, órdenes de campamento y ofrendas de dedicación (Nm 1:8; 2:5; 7:18, 23; 10:15). Todas las traducciones simplemente transliteran (esp. ''Zuar'', fra. ''Tsuar'', ale. ''Zuar''), confirmando un referente único sin variación semántica entre los pasajes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129841, 'spa', 'fluir, desbordar, flotar', 'Los tres contextos muestran el poder del agua: destructivo (el Mar Rojo ahogando al ejército de Egipto), milagroso (hierro flotando), y metafórico (ahogándose en angustia). Las traducciones capturan usos tanto transitivos como intransitivos—agua fluyendo y siendo hecha fluir, objetos flotando y siendo hechos flotar. El tallo Qal aparece en Lamentaciones (las aguas fluyeron), mientras que el Hiphil en Deuteronomio y 2 Reyes enfatiza la causalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129843, 'spa', 'Nombre propio y topónimo', 'Nombre personal y designación territorial. Como antepasado de Samuel, Zuf aparece en genealogías (1 S 1:1; 1 Cr 6:26, 35), y la variante Zofay (1 Cr 6:26) probablemente se refiere al mismo individuo. La ''tierra de Zuf'' (1 S 9:5) marca una región geográfica en Benjamín. Las traducciones transliteran de forma consistente (ing. ''Zuph'', esp. ''Tsuf/Zuf'', fra. ''Zuph''), con algunas mostrando la variante Zofay.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129845, 'spa', 'Nombre propio personal', 'Job 2:11 presenta a Zofar el naamatita como uno de los tres amigos que acuden a acompañar a Job en su duelo. Job 11:1 inicia su primer discurso, donde sostiene que el sufrimiento de Job es menor de lo que su pecado merece. Job 20:1 introduce su segundo discurso sobre el destino de los impíos. Job 42:9 lo incluye en la reprensión divina y la reconciliación final de los amigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129846, 'spa', 'Florecer, brotar (Qal)', 'Sentido intransitivo Qal de florecer, reverdecer, brotar o germinar: el proceso natural de una planta que se abre en flor, usado frecuentemente en sentido figurado. El Salmo 90:6 describe la hierba que «florece» por la mañana; el Salmo 92:7 dice que los impíos «florecen» solo para ser destruidos; el Salmo 103:15 compara la vida humana con la flor del campo. En el Salmo 132:18, la corona del ungido «florecerá», extendiendo la imagen botánica a la gloria regia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129849, 'spa', 'Hacer florecer (Hifil)', 'Sentido causativo Hifil de hacer florecer, producir brotes o hacer germinar algo. En Números 17:8, la vara de Aarón milagrosamente «produjo flores» (vayyatsets tsits), señal divina que validó su autoridad sacerdotal. En Isaías 27:6, Israel en el futuro «florecerá y echará brotes» cuando Dios haga florecer a la nación. La acción causativa subraya la intervención divina como origen del florecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129853, 'spa', 'Atisbar con anhelo', 'Cantares 2:9 retrata al amante «asomándose por la celosía», buscando a su amada. El verbo transmite la cualidad furtiva y apasionada de la escena. Evoca la intensidad del anhelo romántico: el amante incapaz de mantenerse lejos, sus ojos escudriñando cualquier vista de aquella a quien desea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129854, 'spa', 'Angustiar, oprimir (Hifil)', 'Causativo Hifil: angustiar, oprimir o poner en aprietos extremos, especialmente en contextos de asedio y juicio divino. Deuteronomio 28:53-57 lo emplea repetidamente para la presión aplastante del enemigo sitiador. El árabe yudayyiqu (''constriñe'') y el español ''angustiar'' resaltan la cualidad sofocante y opresiva de esta aflicción. Isaías 29:2 lo extiende al propio Dios como agente de angustia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129855, 'spa', 'Opresor (participio sustantivado)', 'Participio Hifil usado como sustantivo: ''el opresor'' o ''los que oprimen''. Isaías 51:13 pregunta dos veces por la furia de hammetziq — el que constriñe. El árabe al-mudayyiqi (''el que constriñe'') conserva la estructura de agente participial. Isaías 29:7 emplea el plural para las naciones que angustian a Ariel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129857, 'spa', 'Presionar, insistir (Hifil)', 'Hifil con fuerza interpersonal: presionar o instar a alguien con persistencia. Dalila presionó a Sansón hasta que su alma se angustió de muerte (Jue 16:16). Job 32:18 lo usa para la compulsión interior del espíritu que constriñe a Elihú a hablar. El coreano ''joruda'' (acosar con insistencia) y el español ''presionar'' distinguen esta insistencia tenaz del asedio militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129862, 'spa', 'derramar, fundir', 'La poesía de Job domina, usando la metalurgia y la abundancia fluyente como imágenes de la creación y bendición de Dios. La ''piedra derramando cobre'' (28:2) captura el proceso de fundición, mientras que ''roca derramando aceite'' (29:6) describe prosperidad pasada en términos hiperbólicos. La ocurrencia en Isaías es textualmente disputada, pero probablemente involucra derramar oración. Las glosas multilingües muestran incertidumbre (corchetes en alemán y francés).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129863, 'spa', 'Angustia de tiempos', 'Daniel 9:25 habla de la reconstrucción de Jerusalén «en estrechez de los tiempos». La expresión española «y en estrechez de» y la francesa «et oppression» confirman el sentido de penuria. La reconstrucción acontecerá, pero no sin dificultad: oposición, escasez y adversidad marcarán la época, tal como los libros de Esdras y Nehemías lo confirman.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129864, 'spa', 'angustia y congoja', 'Las tres ocurrencias usan la frase ''tribulación y angustia'' (tsarah v''tsuqah), sugiriendo un par fijo que describe calamidad comprehensiva. Proverbios advierte de juicio venidero, mientras Isaías describe desastre nacional presente. Las formas entre corchetes en alemán y francés sugieren incertidumbre textual o morfológica, pero el sentido básico permanece claro: restricción severa y angustia. La palabra evoca presión que constríñe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129865, 'spa', 'Sentido principal y más frecuente', 'Sentido principal y más frecuente: rodear una ciudad o fortaleza con fuerzas militares, cortando toda salida y abastecimiento. La construcción típica lleva ''al'' más el nombre de la ciudad (2 S 11:1; 1 R 20:1; 2 R 6:24). El español ''sitiar/asediar'' y el francés ''assiéger'' confirman el sentido bélico de asedio en todas las tradiciones. Deuteronomio 20:19 incluso regula la conducta durante el sitio, mostrando cuán arraigado estaba en la práctica militar israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129869, 'spa', 'Uso constructivo único en Cantares 8', 'Uso constructivo único en Cantares 8:9: ''la cercaremos con tablas de cedro''. Aquí, el acto de rodear es protector u ornamental en lugar de hostil. El español ''la cercaremos'' y el inglés ''we will enclose'' muestran al verbo en su forma más delicada, sugiriendo adorno o resguardo más que confinamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129870, 'spa', 'Atar, amarrar o envolver algo con seguridad en un recipiente o tela', 'Atar, amarrar o envolver algo con seguridad en un recipiente o tela. En 2 Reyes 12:10 se ata dinero en bolsas, y en Ezequiel 5:3 se envuelven unos pocos cabellos en el borde del manto. El español ''atarás'' y el inglés ''bind'' apuntan al sentido concreto y no hostil de sujetar algo cerrándolo, compartiendo la idea raíz de encierro sin contexto militar alguno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129873, 'spa', 'Sentido extendido de oprimir o presionar fuertemente a alguien, causándole angus', 'Sentido extendido de oprimir o presionar fuertemente a alguien, causándole angustia o aflicción. En 2 Crónicas 28:20, Tiglat-piléser ''angustió'' a Acaz en vez de fortalecerlo, y 2 Crónicas 6:28 empareja la imagen del asedio con hambre y peste. El paso del cerco físico a la presión emocional o política es natural, y el español ''angustiar'' lo capta bien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129881, 'spa', 'Hostilidad activa', 'Éxodo 23:22 presenta a Dios prometiendo «seré adversario de tus adversarios», mostrando hostilidad recíproca contra los enemigos de Israel. Deuteronomio 2:9 y 2:19 ordenan a Israel no hostigar ni oprimir a Moab y Amón, ya que esas tierras pertenecen a los descendientes de Lot. Ester 8:11 autoriza a los judíos a destruir a «los que los oprimen» (הַצָּרִים). El término connota agresión deliberada y opresión activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129882, 'spa', 'Formar artesanalmente', 'Aparición textualmente incierta en 1 Reyes 7:15, donde algunos sugieren que describe la fabricación de las columnas de bronce del templo. El español «Y formó» respalda este sentido artesanal. Ya sea tallando, fundiendo o dibujando, el verbo capta la formación creativa, el trabajo de manos hábiles que dan forma al metal o la piedra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129883, 'spa', 'Gran formación natural de piedra — roca, peñasco o risco — que sirve de punto de', 'Gran formación natural de piedra — roca, peñasco o risco — que sirve de punto de referencia, refugio, fuente de agua o lugar de abrigo. Abarca a Moisés golpeando la roca en Horeb (Éx 17:6), Dios colocando a Moisés en la hendidura de la roca (Éx 33:21-22) y las cabras monteses entre los riscos (1 S 24:2). Se distingue del sentido 1 por su contexto narrativo específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129884, 'spa', 'Epíteto divino metafórico — Dios como ''la Roca'' — que denota su fidelidad inmuta', 'Epíteto divino metafórico — Dios como ''la Roca'' — que denota su fidelidad inmutable, su fuerza protectora y su fiabilidad como refugio. Concentrado en el Cántico de Moisés (Dt 32:4, 15, 18, 30, 31) y los salmos davídicos (2 S 22:3, 32, 47; Sal 18:2, 31, 46), este título aparece frecuentemente con sufijos posesivos: ''mi Roca,'' ''nuestra Roca,'' ''su Roca.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129894, 'spa', 'Pedernal — una variedad específica de piedra dura usada para fabricar instrument', 'Pedernal — una variedad específica de piedra dura usada para fabricar instrumentos cortantes afilados. Ambas apariciones se concentran en Josué 5:2-3, donde Josué circuncida a los israelitas con cuchillos de pedernal. El español ''pedernales'' y el inglés ''flint'' convergen en este significado mineral especializado, distinguiéndolo de la ''roca'' genérica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129896, 'spa', 'Filo o borde afilado de un arma — una rara extensión metonímica donde el materia', 'Filo o borde afilado de un arma — una rara extensión metonímica donde el material pétreo se transfiere al instrumento cortante mismo. En Salmo 89:43 se dice que Dios hizo retroceder el ''filo'' de la espada del guerrero, donde la imagen subyacente es la agudeza de la piedra. El español ''filo de'' confirma el desplazamiento de roca-como-sustancia a roca-como-cualidad-cortante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129914, 'spa', 'Nombre propio: Zur', 'Nombre propio que significa ''roca'', aplicado a dos individuos. El príncipe madianita aparece en la narrativa de Baal Peor y los relatos bélicos subsiguientes (Nm 25:15; 31:8; Jos 13:21), mientras que el gabaonita Zur aparece en genealogías benjaminitas (1 Cr 8:30; 9:36). Todas las traducciones transliteran de manera consistente (esp. ''Zur/Tsur'', fra. ''Tzur'', ale. ''Zur''), sin distinción léxica entre ambos portadores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129915, 'spa', 'Forma, patrón o diseño', 'La forma visible, el patrón o el diseño arquitectónico de una estructura o entidad. Se usa casi exclusivamente en Ezequiel 43:11, donde se ordena al profeta describir la forma (tsurat) del templo a Israel: sus salidas, entradas, ordenanzas y toda su disposición. Las traducciones multilingües convergen de manera estrecha: ''forma'' en español y ''form'' en inglés apuntan a un diseño concreto y descriptible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129920, 'spa', 'Líder merarita', 'Mencionado en Números 3:35 como jefe del clan de Merari. El significado de su nombre («mi roca es El») confiesa dependencia de Dios. La consistencia multilingüe (Zuriel en la mayoría de las lenguas) refleja la transliteración estándar de nombres propios hebreos, situando a este individuo en el registro de levitas que cuidaban el tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (129921, 'spa', 'Nombre propio: Zurisadai', 'Nombre propio del padre de Selumiel, de la tribu de Simeón, que significa ''mi roca es Shadai''. Las cinco atestiguaciones emplean la fórmula patronímica ''Selumiel hijo de Zurisadai'' en contextos de censo, disposición del campamento y ofrendas (Nm 1:6; 2:12; 7:36, 41; 10:19). Todas las traducciones transliteran uniformemente el nombre (ing./ale. ''Zurishaddai'', fra. ''Tsurishaddaï'', esp. ''Zurisadai''), preservando el componente teofórico.');